/**
 * Selects a harmonized item entry from the Idle Guild Master 401-item catalog
 * matching the target slot, rarity, and player level progression.
 */
export const selectCatalogItem = (slot: ItemSlot, rarity: Rarity, level: number): ItemCatalogEntry => {
  const slotPool = ITEM_CATALOG.filter(entry => entry.slot === slot);
  if (slotPool.length === 0) {
    return ITEM_CATALOG[0];
  }

  let rarityPool = slotPool.filter(entry => entry.rarity === rarity);
  if (rarityPool.length === 0) {
    if (rarity === Rarity.COMMON) {
      rarityPool = slotPool.filter(e => e.rarity === Rarity.MAGIC || e.rarity === Rarity.RARE);
    } else if (rarity === Rarity.MAGIC) {
      rarityPool = slotPool.filter(e => e.rarity === Rarity.COMMON || e.rarity === Rarity.RARE);
    } else if (rarity === Rarity.RARE) {
      rarityPool = slotPool.filter(e => e.rarity === Rarity.MAGIC || e.rarity === Rarity.UNIQUE);
    } else {
      rarityPool = slotPool.filter(e => e.rarity === Rarity.RARE);
    }
  }
  if (rarityPool.length === 0) {
    rarityPool = slotPool;
  }

  const levelMatched = rarityPool.filter(e => e.minLevel <= Math.max(3, level + 3));
  const candidates = levelMatched.length > 0 ? levelMatched : rarityPool;

  return candidates[Math.floor(Math.random() * candidates.length)];
};

/**
 * Upgrades legacy saved items that lack pixel-art sprites to use the Idle Guild Master item catalog.
 */
export const hydrateLegacyItem = (item: Item | null): Item | null => {
  if (!item) return null;
  if (item.imageUrl && item.imageUrl.startsWith('sprites/items/')) return item;

  const entry = selectCatalogItem(item.type, item.rarity, item.level || 1);
  return {
    ...item,
    name: item.isIdentified ? entry.name : `Unidentified ${entry.name}`,
    trueName: entry.name,
    icon: entry.icon,
    imageUrl: entry.imageUrl,
    flavorText: item.flavorText || entry.flavorText,
    proc: item.proc || ((item.rarity === Rarity.UNIQUE || item.rarity === Rarity.RARE) ? entry.proc : undefined),
  };
};
